// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// Vowel Play text rules: building a puzzle from a name, deciding which names are fair, and judging typed guesses.
// Pure and shared with the server (synced to backend/src/shared).

const EXTRA_FOLD: Record<string, string> = { ø: "o", đ: "d", ł: "l", ß: "ss", æ: "ae", œ: "oe", ð: "d", þ: "th" };

/** Lower case, accents folded, letters and digits only. */
function fold(s: string): string {
  const lower = s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
  return lower.replace(/[øđłßæœðþ]/g, (c) => EXTRA_FOLD[c] ?? c).replace(/[^a-z0-9]/g, "");
}

/** Drops a leading word "The" (only as its own word). */
function dropThe(name: string): string {
  return name.trim().replace(/^the[\s-]+(?=\S)/i, "");
}

/** The letters players see: no vowels (Y stays), no spaces or punctuation, capitals, no leading "The". */
export function toPuzzle(name: string): string {
  return fold(dropThe(name)).replace(/[aeiou]/g, "").toUpperCase();
}

/** Fair to play: at least one vowel came out, and 3 to 16 letters remain. */
export function isUsable(name: string): boolean {
  const full = fold(dropThe(name));
  const puzzle = toPuzzle(name);
  return puzzle.length < full.length && puzzle.length >= 3 && puzzle.length <= 16;
}

/** Removes a bracketed qualifier; null if nothing sensible is left. */
export function cleanName(raw: string): string | null {
  const out = raw.replace(/\s*\([^)]*\)?/g, "").replace(/\s+/g, " ").trim();
  if (!out || out.includes("(") || out.includes(")") || !/[a-z]/i.test(fold(out))) return null;
  return out;
}

/** Optimal string alignment distance (insert, delete, substitute, adjacent swap), early exit above 1. */
function within1(a: string, b: string): boolean {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  if (a.length === b.length) {
    if (a.slice(i + 1) === b.slice(i + 1)) return true; // one wrong letter
    return a[i] === b[i + 1] && a[i + 1] === b[i] && a.slice(i + 2) === b.slice(i + 2); // one swap
  }
  const [long, short] = a.length > b.length ? [a, b] : [b, a];
  return long.slice(i + 1) === short.slice(i); // one missing or extra letter
}

/** Does a typed guess count as the name? Ignores case, accents, spaces, hyphens, punctuation and a leading "the". */
export function matches(guess: string, name: string): boolean {
  const g = fold(guess);
  if (!g) return false;
  const n = fold(name);
  const nameForms = new Set([n, fold(dropThe(name))]);
  const guessForms = new Set([g]);
  if (g.startsWith("the") && g.length > 3) guessForms.add(g.slice(3));
  for (const nf of nameForms) {
    if (!nf) continue;
    for (const gf of guessForms) {
      if (gf === nf) return true;
      if (nf.length >= 8 && within1(gf, nf)) return true;
    }
  }
  return false;
}
